        <script nonce="{{nonce}}">
            (function () {
                if (window.__twelveEarlyB2BAnalyticsInstalled || typeof window.fetch !== 'function') return;
                window.__twelveEarlyB2BAnalyticsInstalled = true;
                window.__twelveNetworkOnlyB2BAnalytics = true;
