                function parseBody(body) {
                    if (!body || typeof body !== 'string') return null;
                    try { return JSON.parse(body); } catch (error) { return null; }
                }

                function operationFrom(payload) {
                    var query = payload && payload.query || '';
                    if (/shoppingListsItemsCreate\s*\(/.test(query)) return 'items_added';
                    if (/shoppingListsCreate\s*\(/.test(query)) return 'list_created';
                    if (/\bshoppingLists?\s*\(/.test(query)) return 'list_query';
                    return '';
                }

                function cacheLists(value) {
                    if (!value || typeof value !== 'object') return;
                    if (!Array.isArray(value)
                        && value.id != null
                        && value.name != null
                        && value.description != null) {
                        window.__twelveB2BListCache[String(value.id)] = {
                            Name: String(value.name || ''),
                            Description: String(value.description || '')
                        };
                    }
                    Object.keys(value).forEach(function (key) { cacheLists(value[key]); });
                }

                function announce(operation, requestPayload, responsePayload) {
                    if (!operation || !responsePayload || (responsePayload.errors && responsePayload.errors.length)) return;

                    console.info('[B2B Analytics Early] Confirmed GraphQL success:', operation, {
                        request: requestPayload,
                        response: responsePayload
                    });

                    var variables = requestPayload && requestPayload.variables || {};
                    var responseData = responsePayload.data || {};
                    cacheLists(responseData);

                    if (operation === 'list_query') return;

                    if (operation === 'list_created') {
                        var createdResult = responseData.shoppingListsCreate || {};
                        var createdList = createdResult.shoppingList || {};
                        var requestedList = variables.shoppingListData || {};
                        var createdId = createdList.id || '';
                        var createdName = createdList.name || requestedList.name || '';
                        var createdDescription = createdList.description || requestedList.description || '';

                        if (createdId) {
                            window.__twelveB2BListCache[String(createdId)] = {
                                Name: createdName,
                                Description: createdDescription
                            };
                        }

                        var createPayload = {
                            Name: createdName,
                            Description: createdDescription,
                            Email: createdList.customerInfo && createdList.customerInfo.email || '{{customer.email}}',
                            shopping_list_id: String(createdId),
                            events: { name: 'Shopping lists created' }
                        };
                        console.info('[B2B Analytics Network] Shopping lists created:', createPayload);
                        if (typeof window.gtag === 'function') {
                            window.gtag('event', 'Shopping lists created', createPayload);
                        }
                    }

                    if (operation === 'items_added') {
                        var shoppingListId = variables.shoppingListId || '';
                        var cachedList = window.__twelveB2BListCache[String(shoppingListId)] || {};
                        var items = Array.isArray(variables.items) ? variables.items : [];
                        var addPayload = {
                            Name: cachedList.Name || '',
                            Description: cachedList.Description || '',
                            Email: '{{customer.email}}',
                            shopping_list_id: String(shoppingListId),
                            product_ids: items.map(function (item) { return item.productId || ''; }).join(','),
                            variant_ids: items.map(function (item) { return item.variantId || ''; }).join(','),
                            quantities: items.map(function (item) { return item.quantity || ''; }).join(','),
                            events: { name: 'Favorited items and items added to shopping lists' }
                        };
                        console.info('[B2B Analytics Network] Items added:', addPayload);
                        if (typeof window.gtag === 'function') {
                            window.gtag('event', 'Favorited items and items added to shopping lists', addPayload);
                        }
                    }
                }

                var originalFetch = window.fetch;
                window.fetch = function (input, init) {
                    var requestUrl = typeof input === 'string' ? input : input && input.url || '';
                    var isB2BGraphql = /^https:\/\/api-b2b\.bigcommerce\.com\/graphql(?:\?|$)/i.test(requestUrl);
                    var requestPayloadPromise = Promise.resolve(parseBody(init && init.body));

                    if (isB2BGraphql
                        && !init?.body
                        && typeof Request !== 'undefined'
                        && input instanceof Request) {
                        requestPayloadPromise = input.clone().text().then(parseBody).catch(function () { return null; });
                    }

                    var responsePromise = originalFetch.apply(this, arguments);
                    if (!isB2BGraphql) return responsePromise;

                    return Promise.all([responsePromise, requestPayloadPromise]).then(function (results) {
                        var response = results[0];
                        var requestPayload = results[1];
                        var operation = operationFrom(requestPayload);

                        if (!operation) return response;

                        console.info('[B2B Analytics Early] Exact GraphQL request detected:', operation, requestPayload);
                        if (!response.ok) return response;

                        response.clone().json().then(function (payload) {
                            announce(operation, requestPayload, payload);
                        }).catch(function () {});
                        return response;
                    });
                };

                if (typeof window.XMLHttpRequest === 'function') {
                    var originalOpen = window.XMLHttpRequest.prototype.open;
                    var originalSend = window.XMLHttpRequest.prototype.send;

                    window.XMLHttpRequest.prototype.open = function (method, url) {
                        this.__twelveB2BUrl = url;
                        return originalOpen.apply(this, arguments);
                    };

                    window.XMLHttpRequest.prototype.send = function (body) {
                        var xhr = this;
                        var requestPayload = parseBody(body);
                        var operation = /api-b2b\.bigcommerce\.com\/graphql/i.test(xhr.__twelveB2BUrl || '')
                            ? operationFrom(requestPayload)
                            : '';

                        if (operation) {
                            console.info('[B2B Analytics Early] GraphQL XHR detected:', operation, requestPayload);
                            xhr.addEventListener('load', function () {
                                if (xhr.status < 200 || xhr.status >= 300) return;
                                var payload = xhr.response && typeof xhr.response === 'object'
                                    ? xhr.response
                                    : parseBody(xhr.responseText);
                                announce(operation, requestPayload, payload);
                            }, { once: true });
                        }

                        return originalSend.apply(this, arguments);
                    };
                }

                console.info('[B2B Analytics Early] GraphQL interceptor installed.');
            }());
        </script>

