        {{#if customer}}
            <script nonce="{{nonce}}">
                (function () {
                    var modeKey = 'account-policy-mode-{{customer.id}}';
                    var configKey = 'account-policy-config-{{customer.id}}';
                    var mode = null;

                    // Older code cached unrestricted accounts. Remove only that stale
                    // value; restricted product/brand configurations remain cached.
                    try {
                        mode = window.sessionStorage.getItem(modeKey);
                        var cachedConfig = window.sessionStorage.getItem(configKey);
                        var cachedEntry = cachedConfig ? JSON.parse(cachedConfig) : null;
                        if (mode === 'unrestricted' || (cachedEntry && cachedEntry.unrestricted === true)) {
                            window.sessionStorage.removeItem(modeKey);
                            window.sessionStorage.removeItem(configKey);
                            mode = null;
                        } else {
                            var cachedConfiguration = cachedEntry && cachedEntry.configuration;
                            var currentCategoryId = Number(document.body.getAttribute('data-account-current-category-id') || 0);
                            var cacheIsFresh = Number(cachedEntry && cachedEntry.cachedAt || 0) > 0
                                && (Date.now() - Number(cachedEntry.cachedAt)) < (30 * 60 * 1000);
                            var hiddenCategoryIds = cachedConfiguration && Array.isArray(cachedConfiguration.categoryIds)
                                ? cachedConfiguration.categoryIds.map(Number)
                                : [];

                            if (cacheIsFresh
                                && currentCategoryId
                                && cachedConfiguration
                                && cachedConfiguration.type === 'brand'
                                && hiddenCategoryIds.indexOf(currentCategoryId) !== -1) {
                                document.documentElement.style.display = 'none';
                                window.location.replace('/');
                                return;
                            }
                        }
                    } catch (error) {
                        window.sessionStorage.removeItem(modeKey);
                        window.sessionStorage.removeItem(configKey);
                        mode = null;
                    }

                    document.documentElement.classList.add('account-policy-loading');
                    if (mode === 'product' || mode === 'brand') {
                        document.documentElement.classList.add('account-policy-' + mode);
                    }
                }());
            </script>
