            <script nonce="{{nonce}}">
                (function () {
                    'use strict';

                    if (document.body.getAttribute('data-auth') !== 'true') return;

                    // B2B authentication constants documented by BigCommerce.
                    var B2B_GRAPHQL_URL = 'https://api-b2b.bigcommerce.com/graphql';
                    var B2B_CLIENT_ID = 'dl7c39mdpul6hyc489yk0vzxl6jesyx';
                    var ACCOUNT_CONFIGURATOR_FIELD = 'Account Configurator';
                    var channelId = Number('{{settings.channel_id}}') || 1;
                    var POLICY_CACHE_MAX_AGE = 30 * 60 * 1000;
                    var policyModeCacheKey = 'account-policy-mode-{{#if customer}}{{customer.id}}{{else}}guest{{/if}}';
                    var policyConfigCacheKey = 'account-policy-config-{{#if customer}}{{customer.id}}{{else}}guest{{/if}}';

                    var contextValue = {{jsContext}};
                    var context = contextValue;

                    if (typeof contextValue === 'string') {
                        try {
                            context = JSON.parse(contextValue);
                        } catch (error) {
                            context = {};
                            console.warn('[Account Configurator] Theme context JSON is invalid.');
                        }
                    }

                    var storefrontToken = context.accountStorefrontToken;
                    var policy = null;
                    var productMeta = new Map();
                    var pendingIds = new Set();
                    var applyTimer = null;
                    var observer = null;
                    var cartBlocked = false;
                    var autoLoadingProducts = false;
                    var redirectingToHome = false;
                    var configuredBrandFacetsReady = false;
                    var accountBrandsRequest = null;
                    var configurationRequest = null;
                    var guardsInstalled = false;
                    var policyApplied = false;

                    function numberSet(values) {
                        return new Set((Array.isArray(values) ? values : []).map(Number).filter(function (id) {
                            return Number.isInteger(id) && id > 0;
                        }));
                    }

                    function normalize(configuration) {
                        if (!configuration || typeof configuration !== 'object' || Array.isArray(configuration)) return null;
                        if (['product', 'brand'].indexOf(configuration.type) === -1) return null;

                        var normalized = {
                            type: configuration.type,
                            categoryIds: numberSet(configuration.categoryIds),
                            brandIds: numberSet(configuration.brandIds),
                            prohibitedBrandIds: numberSet(configuration.prohibitedBrandIds),
                            products: numberSet(configuration.products)
                        };

                        var hasConfiguredIds = normalized.categoryIds.size > 0
                            || normalized.brandIds.size > 0
                            || normalized.prohibitedBrandIds.size > 0
                            || normalized.products.size > 0;

                        // An explicitly saved Brand Levels policy with no allowed brands
                        // means that brand browsing is disabled for this company.
                        return configuration.type === 'brand' || hasConfiguredIds ? normalized : null;
                    }

                    function finishLoading() {
                        if (redirectingToHome) return;
                        document.documentElement.classList.remove('account-policy-loading');
                        document.documentElement.classList.add('account-policy-ready');
                        document.querySelectorAll('[aria-busy="true"]').forEach(function (element) {
                            element.removeAttribute('aria-busy');
                        });
                    }

                    function setBusy() {
                        document.querySelectorAll('.twelve-header, main, .productGrid, [data-cart-content]').forEach(function (element) {
                            element.setAttribute('aria-busy', 'true');
                        });
                    }

                    function productAllowed(id, meta) {
                        if (!policy) return true;

                        var productId = Number(id);
                        var brandId = Number(meta && meta.brandId || 0);

                        // In product mode, the configured product ID is authoritative.
                        // Missing catalog metadata must not hide an explicitly allowed product.
                        if (policy.type === 'product' && !policy.products.has(productId)) return false;
                        if (brandId && policy.prohibitedBrandIds.has(brandId)) return false;
                        if (policy.type === 'product') return true;

                        if (!meta) return false;
                        return policy.brandIds.has(meta.brandId);
                    }

                    function cardId(card) {
                        return Number(card.getAttribute('data-entity-id') || card.getAttribute('data-product-id') || 0);
                    }

                    function normalizedBrandName(value) {
                        return String(value || '').replace(/\s+/g, ' ').trim().toLowerCase();
                    }

                    function populateAccountBrandSelects(brands) {
                        var selects = document.querySelectorAll('[data-account-brand-select]');
                        if (!selects.length) return;

                        var allowedBrands = policy && policy.brandIds.size ? policy.brandIds : null;
                        var prohibitedBrands = policy ? policy.prohibitedBrandIds : new Set();
                        var visibleBrands = brands.filter(function (brand) {
                            return brand.id
                                && brand.name
                                && (!allowedBrands || allowedBrands.has(brand.id))
                                && !prohibitedBrands.has(brand.id);
                        }).sort(function (brandA, brandB) {
                            return brandA.name.localeCompare(brandB.name, undefined, { sensitivity: 'base' });
                        });

                        selects.forEach(function (select) {
                            var selectedValue = select.value;
                            while (select.options.length > 1) select.remove(1);
                            visibleBrands.forEach(function (brand) {
                                var option = document.createElement('option');
                                option.value = brand.name;
                                option.textContent = brand.name;
                                option.setAttribute('data-brand-id', String(brand.id));
                                select.appendChild(option);
                            });
                            if (Array.prototype.some.call(select.options, function (option) {
                                return option.value === selectedValue;
                            })) select.value = selectedValue;
                        });
                    }

                    function loadAccountBrandSelects() {
                        if (!document.querySelector('[data-account-brand-select]')) return Promise.resolve();
                        if (accountBrandsRequest) {
                            return accountBrandsRequest.then(populateAccountBrandSelects);
                        }

                        function navigationBrands() {
                            var brandsById = new Map();
                            document.querySelectorAll('[data-account-brand-id]').forEach(function (link) {
                                var id = Number(link.getAttribute('data-account-brand-id') || 0);
                                var name = String(link.textContent || '').replace(/\s+/g, ' ').trim();
                                if (id && name) brandsById.set(id, { id: id, name: name });
                            });
                            return Array.from(brandsById.values());
                        }

                        if (!storefrontToken) {
                            populateAccountBrandSelects(navigationBrands());
                            return Promise.resolve();
                        }

                        function loadPage(afterCursor, brands) {
                            return fetch('/graphql', {
                                method: 'POST',
                                credentials: 'same-origin',
                                headers: { 'Authorization': 'Bearer ' + storefrontToken, 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                    query: 'query AccountFormBrands($after:String){site{brands(first:50,after:$after){edges{node{entityId name}}pageInfo{hasNextPage endCursor}}}}',
                                    variables: { after: afterCursor || null }
                                })
                            }).then(function (response) {
                                if (!response.ok) throw new Error('Brand options could not be loaded.');
                                return response.json();
                            }).then(function (payload) {
                                var connection = payload && payload.data && payload.data.site && payload.data.site.brands;
                                (connection && connection.edges || []).forEach(function (edge) {
                                    brands.push({ id: Number(edge.node.entityId), name: String(edge.node.name || '').trim() });
                                });
                                if (connection && connection.pageInfo && connection.pageInfo.hasNextPage) {
                                    return loadPage(connection.pageInfo.endCursor, brands);
                                }
                                return brands;
                            });
                        }

                        accountBrandsRequest = loadPage(null, []).catch(function (error) {
                            console.warn('[Account Configurator] ' + error.message);
                            return navigationBrands();
                        });
                        return accountBrandsRequest.then(populateAccountBrandSelects);
                    }

                    function isCategoryOrSearchPage() {
                        return document.body.classList.contains('page_type__category')
                            || document.body.classList.contains('page_type__search');
                    }

                    function facetBrandId(link) {
                        try {
                            var url = new URL(link.getAttribute('href') || '', window.location.origin);
                            return Number(url.searchParams.get('brand') || url.searchParams.get('brand[]') || 0);
                        } catch (error) {
                            return 0;
                        }
                    }

                    function syncConfiguredBrandFacet() {
                        if (!policy || policy.type !== 'brand' || !isCategoryOrSearchPage()) return;
                        var facetHeading = document.querySelector('[accordion-title="brand"]');
                        var facetBlock = facetHeading && facetHeading.closest('.accordion-block');
                        if (facetBlock) {
                            facetBlock.querySelectorAll('.navList-action[data-faceted-search-facet]').forEach(function (link) {
                                var brandId = facetBrandId(link);
                                if (brandId) link.classList.toggle('is-selected', policy.brandIds.has(brandId));
                            });
                            facetBlock.classList.add('account-policy-hidden');
                            facetBlock.setAttribute('aria-hidden', 'true');
                        }

                        // Keep the enforced brand parameters in every regular facet URL.
                        // BigCommerce can then update the PLP/search results through its
                        // normal AJAX flow instead of the policy needing a page redirect.
                        document.querySelectorAll('a[data-faceted-search-facet]').forEach(function (link) {
                            if (facetBlock && facetBlock.contains(link)) return;
                            link.setAttribute('href', configuredBrandUrl(link.getAttribute('href')));
                        });

                        hideConfiguredBrandSelections();
                    }

                    function configuredBrandUrl(href) {
                        var url = new URL(href || window.location.href, window.location.origin);
                        url.searchParams.delete('brand');
                        url.searchParams.delete('brand[]');
                        Array.from(policy.brandIds).sort(function (a, b) { return a - b; }).forEach(function (id) {
                            url.searchParams.append('brand', String(id));
                        });
                        url.searchParams.set('_bc_fsnf', '1');
                        return url.pathname + '?' + url.searchParams.toString() + url.hash;
                    }

                    function hideConfiguredBrandSelections() {
                        if (!policy || policy.type !== 'brand' || !isCategoryOrSearchPage()) return;

                        document.querySelectorAll('.facetedSearch-refineFilters').forEach(function (refineFilters) {
                            refineFilters.querySelectorAll('[data-account-selected-facet="brand"]').forEach(function (item) {
                                item.remove();
                            });

                            var remainingItems = refineFilters.querySelectorAll('.inlineList li').length;
                            var clearAll = refineFilters.querySelector(':scope > a[data-faceted-search-facet]');
                            refineFilters.classList.toggle('account-policy-hidden', remainingItems === 0);

                            if (clearAll) {
                                clearAll.classList.toggle('account-policy-hidden', remainingItems === 0);
                                clearAll.setAttribute('href', configuredBrandUrl(clearAll.getAttribute('href')));
                            }

                            var facetContainer = refineFilters.closest('#faceted-search-container') || document;
                            facetContainer.querySelectorAll('[data-twelve-mobile-filter-clear]').forEach(function (button) {
                                button.classList.toggle('account-policy-hidden', remainingItems === 0);
                            });
                            facetContainer.querySelectorAll('[data-twelve-mobile-filter-count]').forEach(function (count) {
                                count.textContent = remainingItems || '';
                            });
                        });
                    }

                    function ensureConfiguredBrandFacets() {
                        if (!policy || policy.type !== 'brand' || !isCategoryOrSearchPage() || policy.brandIds.size === 0) {
                            return false;
                        }
                        if (configuredBrandFacetsReady) return false;

                        var url = new URL(window.location.href);
                        var expectedIds = Array.from(policy.brandIds).sort(function (a, b) { return a - b; });
                        var currentIds = url.searchParams.getAll('brand').concat(url.searchParams.getAll('brand[]')).map(Number).filter(function (id) {
                            return Number.isInteger(id) && id > 0;
                        }).sort(function (a, b) { return a - b; });
                        var alreadySelected = expectedIds.length === currentIds.length
                            && expectedIds.every(function (id, index) { return id === currentIds[index]; });

                        if (alreadySelected) {
                            configuredBrandFacetsReady = true;
                            return false;
                        }

                        url.searchParams.delete('brand');
                        url.searchParams.delete('brand[]');
                        expectedIds.forEach(function (id) { url.searchParams.append('brand', String(id)); });
                        url.searchParams.set('_bc_fsnf', '1');
                        redirectingToHome = true;
                        window.location.replace(url.pathname + '?' + url.searchParams.toString() + url.hash);
                        return true;
                    }

                    function syncBrandFacet(grid, listing) {
                        if (!grid || !listing) return;

                        var visibleBrandCounts = new Map();
                        grid.querySelectorAll(':scope > .product:not(.account-policy-hidden) .card[data-product-brand]').forEach(function (card) {
                            var brandName = normalizedBrandName(card.getAttribute('data-product-brand'));
                            if (brandName) visibleBrandCounts.set(brandName, (visibleBrandCounts.get(brandName) || 0) + 1);
                        });

                        var facetHeading = document.querySelector('[accordion-title="brand"]');
                        var facetBlock = facetHeading && facetHeading.closest('.accordion-block');
                        if (!facetBlock) return;

                        var visibleOptions = 0;
                        facetBlock.querySelectorAll('.navList-item').forEach(function (item) {
                            var link = item.querySelector('.navList-action');
                            if (!link) return;

                            var brandName = normalizedBrandName(Array.prototype.reduce.call(link.childNodes, function (text, node) {
                                return node.nodeType === Node.TEXT_NODE ? text + ' ' + node.textContent : text;
                            }, ''));
                            var count = visibleBrandCounts.get(brandName) || 0;
                            var countElement = link.querySelector('.twelve-facet-option-count');

                            item.classList.toggle('account-policy-hidden', count === 0);
                            if (countElement) countElement.textContent = String(count);
                            if (count > 0) visibleOptions += 1;
                        });

                        facetBlock.classList.toggle(
                            'account-policy-hidden',
                            (policy.type === 'brand' && isCategoryOrSearchPage()) || visibleOptions === 0
                        );
                    }

                    function collectProductIds(root) {
                        var ids = [];
                        (root || document).querySelectorAll('[data-entity-id], [data-product-id]').forEach(function (element) {
                            var id = cardId(element);
                            if (id > 0 && !productMeta.has(id)) ids.push(id);
                        });
                        if (context.productId && !productMeta.has(Number(context.productId))) ids.push(Number(context.productId));
                        return Array.from(new Set(ids));
                    }

                    function approvedProductIdsForCategory(categoryId) {
                        return Array.from(policy.products).filter(function (productId) {
                            var meta = productMeta.get(productId);
                            return meta
                                && productAllowed(productId, meta)
                                && meta.categoryIds.has(Number(categoryId));
                        });
                    }

                    function graphQLProducts(ids) {
                        if (!ids.length || !storefrontToken) return Promise.resolve();
                        var chunks = [];
                        for (var index = 0; index < ids.length; index += 50) chunks.push(ids.slice(index, index + 50));

                        function loadChunk(chunk, attempt) {
                            return fetch('/graphql', {
                                method: 'POST',
                                credentials: 'same-origin',
                                headers: { 'Authorization': 'Bearer ' + storefrontToken, 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                    query: 'query AccountProducts($ids:[Int!]){site{products(entityIds:$ids,first:50){edges{node{entityId brand{entityId} categories(first:50){edges{node{entityId}}}}}}}}',
                                    variables: { ids: chunk }
                                })
                            }).then(function (response) {
                                if (!response.ok) throw new Error('Catalog lookup failed.');
                                return response.json();
                            }).then(function (payload) {
                                if (payload && payload.errors && payload.errors.length) {
                                    throw new Error(payload.errors.map(function (error) {
                                        return error.message;
                                    }).join(' '));
                                }
                                var edges = payload && payload.data && payload.data.site && payload.data.site.products && payload.data.site.products.edges;
                                if (!Array.isArray(edges)) throw new Error('Catalog lookup returned no product data.');
                                (edges || []).forEach(function (edge) {
                                    var node = edge.node;
                                    productMeta.set(Number(node.entityId), {
                                        brandId: Number(node.brand && node.brand.entityId || 0),
                                        categoryIds: new Set(((node.categories && node.categories.edges) || []).map(function (category) {
                                            return Number(category.node.entityId);
                                        }))
                                    });
                                });
                                chunk.forEach(function (id) {
                                    if (!productMeta.has(id)) productMeta.set(id, { brandId: 0, categoryIds: new Set() });
                                });
                            }).catch(function (error) {
                                if (attempt < 2) return loadChunk(chunk, attempt + 1);
                                throw error;
                            });
                        }

                        return Promise.all(chunks.map(function (chunk) {
                            return loadChunk(chunk, 0);
                        }));
                    }

                    function filterProducts(root) {
                        (root || document).querySelectorAll('.card[data-entity-id], .product[data-product-id]').forEach(function (card) {
                            var id = cardId(card);
                            var container = card.matches('.product') ? card : (card.closest('.product') || card);
                            var meta = productMeta.get(id);

                            // Product cards already contain the BigCommerce brand ID. Use it
                            // when the Storefront GraphQL lookup is missing or unavailable.
                            if (!meta) {
                                meta = {
                                    brandId: Number(card.getAttribute('data-brand-id') || 0),
                                    categoryIds: new Set()
                                };
                            }

                            container.classList.toggle('account-policy-hidden', !productAllowed(id, meta));
                            container.classList.remove('account-policy-pending');
                        });
                        document.querySelectorAll('.productGrid').forEach(function (grid) {
                            var products = Array.prototype.slice.call(grid.querySelectorAll(':scope > .product'));
                            var visibleProducts = products.filter(function (item) {
                                return !item.classList.contains('account-policy-hidden');
                            });
                            var visible = visibleProducts.length > 0;
                            var section = grid.closest('section');
                            if (section) section.classList.toggle('account-policy-hidden', !visible);

                            var listing = grid.closest('#product-listing-container') || grid.parentElement;
                            var hasMoreProductsToCheck = Boolean(
                                listing && listing.querySelector('[data-twelve-load-more-button]')
                            );
                            var page = grid.closest('.twelve-category-page');
                            var emptyMessage = page && page.querySelector('[data-account-empty-products]');
                            if (emptyMessage) {
                                var showEmptyMessage = !visible && !hasMoreProductsToCheck;
                                emptyMessage.hidden = !showEmptyMessage;
                                emptyMessage.classList.toggle('account-policy-hidden', !showEmptyMessage);
                            }

                            var totalSource = listing && listing.querySelector('[data-twelve-total-source]');

                            if (listing) {
                                listing.querySelectorAll('.twelve-category-toolbar, [data-twelve-load-more]').forEach(function (summary) {
                                    summary.classList.toggle('account-policy-hidden', !visible);
                                });
                            }

                            if (listing && totalSource) {
                                var originalTotal = Number(totalSource.getAttribute('data-twelve-total-source')) || products.length;
                                var hasMorePages = Boolean(listing.querySelector('[data-twelve-load-more-button]'));
                                var hiddenLoaded = products.length - visibleProducts.length;
                                var filteredTotal = hasMorePages
                                    ? Math.max(visibleProducts.length, originalTotal - hiddenLoaded)
                                    : visibleProducts.length;

                                if (policy.type === 'product' && document.body.classList.contains('page_type__category')) {
                                    var currentCategoryId = Number(
                                        document.body.getAttribute('data-account-current-category-id') || 0
                                    );
                                    if (currentCategoryId) {
                                        var approvedCategoryTotal = approvedProductIdsForCategory(currentCategoryId).length;
                                        filteredTotal = Math.max(visibleProducts.length, approvedCategoryTotal);
                                    }
                                }

                                listing.querySelectorAll('[data-twelve-showing-count], [data-twelve-loaded-count]').forEach(function (count) {
                                    count.textContent = String(visibleProducts.length);
                                });
                                listing.querySelectorAll('[data-twelve-total-count], [data-twelve-load-total]').forEach(function (count) {
                                    count.textContent = String(filteredTotal);
                                });

                                var progress = listing.querySelector('[data-twelve-load-progress]');
                                if (progress) {
                                    progress.style.width = (filteredTotal > 0
                                        ? Math.min(100, (visibleProducts.length / filteredTotal) * 100)
                                        : 0) + '%';
                                }

                                syncBrandFacet(grid, listing);
                            }
                        });
                    }

                    function filterNavigation() {
                        document.querySelectorAll('[data-account-brand-id]').forEach(function (link) {
                            var brandId = Number(link.getAttribute('data-account-brand-id'));
                            var hidden = policy.prohibitedBrandIds.has(brandId) || (policy.type === 'brand' && !policy.brandIds.has(brandId));
                            (link.closest('li') || link).classList.toggle('account-policy-hidden', hidden);
                        });

                        var categoryContainerSelector = [
                            '.twelve-nav-item[data-account-category-id]',
                            '.twelve-category-group[data-account-category-id]',
                            'li:has(> a[data-account-category-id])'
                        ].join(',');
                        var navigation = document.querySelector('.twelve-navigation');
                        var categoryContainers = navigation
                            ? Array.prototype.slice.call(navigation.querySelectorAll(categoryContainerSelector))
                            : [];

                        if (policy.type === 'brand') {
                            // Work from leaves to roots. An explicit numeric ID always hides
                            // its node; an unlisted parent remains only while a child survives.
                            categoryContainers.slice().reverse().forEach(function (container) {
                                var ownLink = container.matches('[data-account-category-id]')
                                    ? container
                                    : container.querySelector(':scope > a[data-account-category-id]');
                                var categoryId = Number(ownLink && ownLink.getAttribute('data-account-category-id') || 0);
                                var childContainers = categoryContainers.filter(function (candidate) {
                                    return candidate !== container
                                        && candidate.parentElement
                                        && candidate.parentElement.closest(categoryContainerSelector) === container;
                                });
                                var originallyHadChildren = childContainers.length > 0;
                                var hasVisibleChild = childContainers.some(function (child) {
                                    return !child.classList.contains('account-policy-hidden');
                                });
                                var hidden = policy.categoryIds.has(categoryId)
                                    || (originallyHadChildren && !hasVisibleChild);

                                container.classList.toggle('account-policy-hidden', hidden);
                            });
                        } else {
                            // Product-level navigation treats category IDs as the allowed tree.
                            categoryContainers.forEach(function (container) {
                                var ownLink = container.matches('[data-account-category-id]')
                                    ? container
                                    : container.querySelector(':scope > a[data-account-category-id]');
                                var categoryId = Number(ownLink && ownLink.getAttribute('data-account-category-id') || 0);
                                var descendantIds = Array.prototype.map.call(
                                    container.querySelectorAll('a[data-account-category-id]'),
                                    function (link) { return Number(link.getAttribute('data-account-category-id')); }
                                );
                                var visible = policy.categoryIds.has(categoryId)
                                    || descendantIds.some(function (id) { return policy.categoryIds.has(id); });
                                container.classList.toggle('account-policy-hidden', !visible);
                            });
                        }

                        document.querySelectorAll('[data-account-brands-menu]').forEach(function (menu) {
                            menu.classList.toggle(
                                'account-policy-hidden',
                                policy.type === 'brand' && policy.brandIds.size === 0
                            );
                        });

                        var hiddenUrls = new Set();
                        document.querySelectorAll('.twelve-navigation a.account-policy-hidden, .twelve-navigation .account-policy-hidden a').forEach(function (link) {
                            try { hiddenUrls.add(new URL(link.href, window.location.origin).pathname.replace(/\/$/, '')); } catch (error) { /* Ignore malformed Page Builder links. */ }
                        });
                        document.querySelectorAll('a[href]').forEach(function (link) {
                            if (link.closest('.twelve-navigation')) return;
                            var path;
                            try { path = new URL(link.href, window.location.origin).pathname.replace(/\/$/, ''); } catch (error) { return; }
                            var target = link.closest('li') || link;
                            target.classList.toggle('account-policy-category-hidden', hiddenUrls.has(path));
                        });
                    }

                    function loadUntilVisibleProducts() {
                        var listing = document.querySelector('#product-listing-container');
                        var grid = listing && listing.querySelector('.productGrid');
                        var visibleProduct = grid && grid.querySelector(':scope > .product:not(.account-policy-hidden)');
                        var button = listing && listing.querySelector('[data-twelve-load-more-button]');

                        if (!grid || !button || (visibleProduct && policy.type !== 'product')) return Promise.resolve();

                        if (policy.type === 'product' && document.body.classList.contains('page_type__category')) {
                            var currentCategoryId = Number(
                                document.body.getAttribute('data-account-current-category-id') || 0
                            );

                            if (currentCategoryId) {
                                var expectedProductIds = approvedProductIdsForCategory(currentCategoryId);
                                var loadedProductIds = new Set();

                                grid.querySelectorAll(':scope > .product [data-entity-id], :scope > .product[data-product-id]').forEach(function (card) {
                                    var productId = cardId(card);
                                    if (productId) loadedProductIds.add(productId);
                                });

                                var categoryProductsLoaded = expectedProductIds.every(function (productId) {
                                    return loadedProductIds.has(productId);
                                });

                                if (categoryProductsLoaded) {
                                    button.remove();
                                    filterProducts(document);
                                    return Promise.resolve();
                                }
                            }
                        }

                        var nextUrl = button.getAttribute('href');
                        if (!nextUrl) return Promise.resolve();

                        autoLoadingProducts = true;
                        button.classList.add('is-loading');
                        button.setAttribute('aria-disabled', 'true');
                        button.innerHTML = '<span>Loading…</span>';

                        function fetchNextProductPage(attempt) {
                            return fetch(nextUrl, { credentials: 'same-origin' }).then(function (response) {
                                if (!response.ok) throw new Error('Unable to load the next product page.');
                                return response.text();
                            }).catch(function (error) {
                                if (attempt < 2) return fetchNextProductPage(attempt + 1);
                                throw error;
                            });
                        }

                        return fetchNextProductPage(0)
                            .then(function (html) {
                                var page = new DOMParser().parseFromString(html, 'text/html');
                                var newProducts = Array.prototype.slice.call(
                                    page.querySelectorAll('#product-listing-container .productGrid > .product')
                                );
                                var nextButton = page.querySelector('[data-twelve-load-more-button]');

                                var existingProductIds = new Set();
                                grid.querySelectorAll(':scope > .product').forEach(function (product) {
                                    var productCard = product.matches('[data-entity-id], [data-product-id]')
                                        ? product
                                        : product.querySelector('[data-entity-id], [data-product-id]');
                                    var productId = productCard ? cardId(productCard) : 0;
                                    if (productId) existingProductIds.add(productId);
                                });

                                var appendedProducts = 0;
                                newProducts.forEach(function (product) {
                                    var productCard = product.matches('[data-entity-id], [data-product-id]')
                                        ? product
                                        : product.querySelector('[data-entity-id], [data-product-id]');
                                    var productId = productCard ? cardId(productCard) : 0;
                                    if (productId && existingProductIds.has(productId)) return;
                                    if (productId) existingProductIds.add(productId);
                                    grid.appendChild(product);
                                    appendedProducts++;
                                });

                                var followingUrl = nextButton && nextButton.getAttribute('href');
                                if (followingUrl && (appendedProducts > 0 || followingUrl !== nextUrl)) {
                                    button.setAttribute('href', followingUrl);
                                    button.classList.remove('is-loading');
                                    button.removeAttribute('aria-disabled');
                                    button.innerHTML = '<span>Load more</span>';
                                } else {
                                    button.remove();
                                }

                                var newIds = collectProductIds(grid);
                                return graphQLProducts(newIds).then(function () {
                                    filterProducts(document);
                                    return loadUntilVisibleProducts();
                                });
                            })
                            .catch(function (error) {
                                button.classList.remove('is-loading');
                                button.removeAttribute('aria-disabled');
                                button.innerHTML = '<span>Load more</span>';
                                console.warn('[Account Configurator] ' + error.message);
                            })
                            .then(function () {
                                autoLoadingProducts = false;
                            });
                    }

                    function blockPdpIfNeeded() {
                        var productView = document.querySelector('.productView[data-entity-id], .twelve-pdp[data-entity-id]');
                        var productId = Number(context.productId || (productView && productView.getAttribute('data-entity-id')) || 0);
                        if (!productId || productAllowed(productId, productMeta.get(productId))) return;
                        redirectingToHome = true;
                        window.location.replace('/');
                    }

                    function resolveCurrentBrandId(afterCursor) {
                        var brandId = Number(document.body.getAttribute('data-account-current-brand-id') || 0);
                        var brandProduct = document.querySelector('.page_type__brand .card[data-brand-id], body.page_type__brand .card[data-brand-id]');

                        if (!document.body.classList.contains('page_type__brand')) return Promise.resolve(0);
                        if (!brandId && brandProduct) {
                            brandId = Number(brandProduct.getAttribute('data-brand-id') || 0);
                        }

                        if (!brandId && document.body.classList.contains('page_type__brand')) {
                            var currentPath = window.location.pathname.replace(/\/$/, '');
                            var matchingBrandLink = Array.prototype.find.call(
                                document.querySelectorAll('[data-account-brand-id][href]'),
                                function (link) {
                                    return new URL(link.href, window.location.origin).pathname.replace(/\/$/, '') === currentPath;
                                }
                            );
                            brandId = Number(matchingBrandLink && matchingBrandLink.getAttribute('data-account-brand-id') || 0);
                        }

                        if (brandId) return Promise.resolve(brandId);
                        if (!storefrontToken) return Promise.resolve(0);

                        return fetch('/graphql', {
                            method: 'POST',
                            credentials: 'same-origin',
                            headers: { 'Authorization': 'Bearer ' + storefrontToken, 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                query: 'query AccountBrandPage($after:String){site{brands(first:50,after:$after){edges{node{entityId path}}pageInfo{hasNextPage endCursor}}}}',
                                variables: { after: afterCursor || null }
                            })
                        }).then(function (response) {
                            if (!response.ok) throw new Error('Brand lookup failed.');
                            return response.json();
                        }).then(function (payload) {
                            var connection = payload && payload.data && payload.data.site && payload.data.site.brands;
                            var currentPath = window.location.pathname.replace(/\/$/, '');
                            var match = connection && (connection.edges || []).find(function (edge) {
                                return String(edge.node.path || '').replace(/\/$/, '') === currentPath;
                            });

                            if (match) return Number(match.node.entityId);
                            if (connection && connection.pageInfo && connection.pageInfo.hasNextPage) {
                                return resolveCurrentBrandId(connection.pageInfo.endCursor);
                            }
                            return 0;
                        }).catch(function (error) {
                            console.warn('[Account Configurator] ' + error.message);
                            return 0;
                        });
                    }

                    function blockBrandPageIfNeeded() {
                        var currentPath = window.location.pathname.replace(/\/+$/, '') || '/';
                        if (policy.type === 'brand' && policy.brandIds.size === 0
                            && (currentPath === '/brands' || document.body.classList.contains('page_type__brand'))) {
                            redirectingToHome = true;
                            window.location.replace('/');
                            return Promise.resolve();
                        }

                        return resolveCurrentBrandId().then(function (brandId) {
                            var isProhibited = brandId && policy.prohibitedBrandIds.has(brandId);
                            var isOutsideBrandCatalogue = brandId
                                && policy.type === 'brand'
                                && !policy.brandIds.has(brandId);

                            if (isProhibited || isOutsideBrandCatalogue) {
                                redirectingToHome = true;
                                window.location.replace('/');
                            }
                        });
                    }

                    function blockCategoryPageIfNeeded() {
                        if (policy.type !== 'brand' || !document.body.classList.contains('page_type__category')) {
                            return false;
                        }

                        var categoryId = Number(document.body.getAttribute('data-account-current-category-id') || 0);
                        var activeCategoryLink = document.querySelector(
                            '.twelve-navigation a[data-account-category-id][aria-current="page"]'
                        );

                        if (!categoryId && activeCategoryLink) {
                            categoryId = Number(activeCategoryLink.getAttribute('data-account-category-id') || 0);
                        }

                        var categoryIsHidden = categoryId && policy.categoryIds.has(categoryId);
                        if (!categoryIsHidden && activeCategoryLink) {
                            categoryIsHidden = Boolean(activeCategoryLink.closest('.account-policy-hidden'));
                        }

                        if (!categoryIsHidden) return false;

                        redirectingToHome = true;
                        window.location.replace('/');
                        return true;
                    }

                    function applyPolicy(root) {
                        if (!policy) return Promise.resolve();
                        if (ensureConfiguredBrandFacets()) return Promise.resolve();
                        collectProductIds(root).forEach(function (id) { pendingIds.add(id); });
                        var ids = Array.from(pendingIds);
                        pendingIds.clear();
                        return graphQLProducts(ids).then(function () {
                            filterProducts(root);
                            syncConfiguredBrandFacet();
                            filterNavigation();
                            if (blockCategoryPageIfNeeded()) return Promise.resolve();
                            blockPdpIfNeeded();
                            return blockBrandPageIfNeeded().then(loadUntilVisibleProducts);
                        });
                    }

                    function showCartWarning(restrictedItemIds) {
                        document.querySelectorAll('[data-cart-item-id]').forEach(function (line) {
                            line.classList.toggle('account-policy-restricted-line', restrictedItemIds.has(line.getAttribute('data-cart-item-id')));
                        });
                        var cart = document.querySelector('[data-cart]');
                        if (!cart) return;
                        var existing = cart.querySelector('[data-account-cart-alert]');
                        if (restrictedItemIds.size) {
                            cartBlocked = true;
                            if (!existing) {
                                existing = document.createElement('div');
                                existing.className = 'account-policy-alert';
                                existing.setAttribute('data-account-cart-alert', '');
                                existing.setAttribute('role', 'alert');
                                existing.textContent = 'Your cart contains a product that is unavailable for this account. Remove the highlighted item before checkout.';
                                var status = cart.querySelector('[data-cart-status]');
                                (status || cart).prepend(existing);
                            }
                            document.querySelectorAll('a[href*="checkout"], [data-primary-checkout-now-action]').forEach(function (button) {
                                button.setAttribute('aria-disabled', 'true');
                                button.classList.add('is-disabled');
                            });
                        } else {
                            cartBlocked = false;
                            if (existing) existing.remove();
                        }
                    }

                    function validateCart() {
                        if (!policy || !context.cartId) return Promise.resolve();
                        return fetch('/api/storefront/carts/' + encodeURIComponent(context.cartId), { credentials: 'same-origin' })
                            .then(function (response) { return response.ok ? response.json() : null; })
                            .then(function (cart) {
                                if (!cart) return;
                                var items = [].concat(cart.lineItems && cart.lineItems.physicalItems || [], cart.lineItems && cart.lineItems.digitalItems || []);
                                var ids = items.map(function (item) { return Number(item.productId); }).filter(Boolean);
                                return graphQLProducts(ids).then(function () {
                                    var restricted = new Set();
                                    items.forEach(function (item) {
