            {{#if page_type '!=' 'login'}}



                <section class="twelve-guest-screen" aria-labelledby="guest-screen-title">
                    <div class="twelve-guest-art" aria-hidden="true">
                        <div class="twelve-guest-art-inner">
                            <span class="twelve-guest-kicker">Product-obsessed since 2005</span>
                            <h2>Made Possible By Twelve.</h2>
                            <p>Custom packaging, merchandise and gifting for the world's most iconic brands.</p>
                            <span class="twelve-guest-locations">Brooklyn · London · Paris</span>
                        </div>
                    </div>

                    <div class="twelve-guest-content">
                        <div class="twelve-guest-card">
                            <div class="twelve-guest-logo">
                                {{> components/common/store-logo}}
                            </div>
                            <h1 hidden>Twelve — packaging, premiums and gifting</h1>
                            <h3 id="guest-screen-title">Access the collection</h3>
                            <p>Sign in to browse products and manage your account. New to Twelve? Register to get started.</p>

                            <div class="twelve-guest-actions">
                                <button class="btn-with-outline event-open-signin" type="button">
                                    <span>{{lang 'category.login_required.button'}}</span>
                                </button>
                                <button class="btn-with-outline event-open-signup" type="button">
                                    <span>{{lang 'common.sign_up'}}</span>
                                </button>
                            </div>
                        </div>
                    </div>
                </section>

            {{else}}

                {{> components/common/body }}

            {{/if}}


        {{/if}}
        
        {{> components/common/user-authentication }}
        
        {{{footer.scripts}}}
        
        <script>
            (function () {
              function checkLogoutUrl() {
                  if (location.href.includes("#/login") && !location.href.includes("loginFlag=receivePassword")) {
                      setTimeout(() => {
                        window.location.replace("/");
                      }, 1000);
                  }
              }
              // Detect browser back/forward
              window.addEventListener("popstate", checkLogoutUrl);
        
              // Detect pushState
              const pushState = history.pushState;
              history.pushState = function () {
                  pushState.apply(history, arguments);
                  checkLogoutUrl();
              };
        
              // Detect replaceState
              const replaceState = history.replaceState;
              history.replaceState = function () {
                  replaceState.apply(history, arguments);
                  checkLogoutUrl();
              };
        
              // Initial check
              checkLogoutUrl();
          })();
        </script>

        <script nonce="{{nonce}}">
            (function () {
                function cleanText(element) {
                    return element ? (element.textContent || '').replace(/\s+/g, ' ').trim() : '';
                }

                function sendClickEvent(eventName, details) {
                    var eventPayload = Object.assign({
                        id: '{{customer.id}}',
                        email: '{{customer.email}}',
                        page_type: '{{page_type}}',
                        page_url: window.location.href,
                        events: { name: eventName }
                    }, details);

                    console.info('[Analytics] Event ready:', eventName, eventPayload);

                    if (typeof window.gtag !== 'function') {
                        console.warn('[Analytics] gtag is not available:', eventName);
                        return;
                    }

                    window.gtag('event', eventName, eventPayload);
                    console.info('[Analytics] Event queued in dataLayer:', eventName);
                }

                document.addEventListener('submit', function (event) {
                    var form = event.target;
                    if (!form || !form.matches('[data-quick-search-form], [data-advanced-search-form], form[action*="/search"]')) return;

                    var queryInput = form.querySelector('[data-search-quick], [name="search_query"], [name="search_query_adv"]');
                    var brandSelect = form.querySelector('[name="brand"]');
                    var categorySelect = form.querySelector('[name="category"]');
                    var categoryInputs = form.querySelectorAll('[name="category[]"]');
                    var selectedBrand = brandSelect && brandSelect.options ? brandSelect.options[brandSelect.selectedIndex] : null;
                    var selectedCategory = categorySelect && categorySelect.options ? categorySelect.options[categorySelect.selectedIndex] : null;

                    sendClickEvent('Search criteria', {
                        search_term: queryInput ? queryInput.value.trim() : '',
                        search_type: form.hasAttribute('data-advanced-search-form') ? 'advanced' : 'quick',
                        brand_id: brandSelect ? brandSelect.value : '',
                        brand_name: selectedBrand ? cleanText(selectedBrand) : '',
                        category_id: categoryInputs.length
                            ? Array.prototype.map.call(categoryInputs, function (input) { return input.value; }).join(',')
                            : categorySelect ? categorySelect.value : '',
                        category_name: selectedCategory ? cleanText(selectedCategory) : '',
                        include_subcategories: !!form.querySelector('[name="searchsubs"]:checked'),
                        price_from: (form.querySelector('[name="price_from"]') || {}).value || '',
                        price_to: (form.querySelector('[name="price_to"]') || {}).value || '',
                        featured: (form.querySelector('[name="featured"]') || {}).value || '',
                        shipping: (form.querySelector('[name="shipping"]') || {}).value || '',
                        click_location: form.hasAttribute('data-advanced-search-form') ? 'Advanced search' : 'Header search'
                    });
                });

                document.addEventListener('click', function (event) {
                    var link = event.target.closest('a, button');
                    if (!link) return;

                    var facetContent = link.closest('.accordion-content[data-facet-title]');
                    if (facetContent
                        && link.matches('[data-faceted-search-facet]')
                        && /material/i.test(facetContent.getAttribute('data-facet-title') || '')) {
                        var filterValue = link.cloneNode(true);
                        Array.prototype.forEach.call(
                            filterValue.querySelectorAll('.twelve-facet-option-count, .navList-action-close'),
                            function (element) { element.remove(); }
                        );

                        sendClickEvent('Filter selections', {
                            filter_type: 'Material',
                            filter_value: cleanText(filterValue),
                            selection_action: link.classList.contains('is-selected') ? 'remove' : 'add',
                            category_name: cleanText(document.querySelector('.top-category-hero__title')),
                            click_location: 'Product filters'
                        });
                        return;
                    }

                    var navigationItem = link.closest('.twelve-nav-item');
                    var megaMenu = link.closest('.twelve-mega');

                    var orderRequestLink = link.closest('.twelve-cart__summary .twelve-button--block[href*="submit-order-request"]');
                    if (orderRequestLink) {
                        var cartSummaryValues = document.querySelectorAll('.twelve-cart__summary-list dd');
                        var cartRows = document.querySelectorAll('.twelve-cart-line[data-cart-item-id]');

                        sendClickEvent('Cart abandonment', {
                            cart_items: cartSummaryValues[0] ? cleanText(cartSummaryValues[0]) : '',
                            cart_units: cartSummaryValues[1] ? cleanText(cartSummaryValues[1]) : '',
                            cart_subtotal: cartSummaryValues[2] ? cleanText(cartSummaryValues[2]) : '',
                            cart_item_ids: Array.prototype.map.call(cartRows, function (row) {
                                return row.getAttribute('data-cart-item-id') || '';
                            }).join(','),
                            cart_item_names: Array.prototype.map.call(cartRows, function (row) {
                                return cleanText(row.querySelector('h2'));
                            }).join(', '),
                            link_text: cleanText(orderRequestLink),
                            link_url: orderRequestLink.href || '',
                            click_location: 'Cart summary'
                        });
                        return;
                    }

                    if (navigationItem
                        && link.closest('.twelve-navigation')
                        && /^contact(?: us)?$/i.test(cleanText(link))) {
                        sendClickEvent('Contact Us clicks', {
                            link_text: cleanText(link),
                            link_url: link.href || '',
                            click_location: 'Menu'
                        });
                        return;
                    }

                    var contactEmailLink = link.closest('.twelve-contact__offices a[href^="mailto:"]');
                    if (contactEmailLink) {
                        var contactOffice = contactEmailLink.closest('.twelve-contact__office');

                        sendClickEvent('Email address clicks', {
                            email_address: (contactEmailLink.getAttribute('href') || '').replace(/^mailto:/i, ''),
                            office: cleanText(contactOffice && contactOffice.querySelector('.twelve-contact__eyebrow')),
                            link_text: cleanText(contactEmailLink),
                            link_url: contactEmailLink.href || '',
                            click_location: 'Contact page'
                        });
                        return;
                    }

                    var footerLink = link.closest('.twelve-footer a');
                    if (footerLink) {
                        if (/\/our-story\/?(?:[?#].*)?$/.test(footerLink.href || '')) {
                            sendClickEvent('Our Story Click', {
                                link_text: cleanText(footerLink),
                                link_url: footerLink.href || '',
                                click_location: 'Footer'
                            });
                            return;
                        }

                        var footerCategoryRegion = footerLink.closest(
                            '[data-content-region="footer_links_1--global"]'
                        );

                        if (footerCategoryRegion) {
                            sendClickEvent('Category clicks', {
                                category_name: cleanText(footerLink),
                                link_text: cleanText(footerLink),
                                link_url: footerLink.href || '',
                                click_location: 'Footer - Shop'
                            });
                            return;
                        }

                        var footerLinkDescription = [
                            cleanText(footerLink),
                            footerLink.getAttribute('aria-label') || '',
                            footerLink.getAttribute('title') || '',
                            footerLink.href || ''
                        ].join(' ');
                        var footerEventName = '';

                        if (/techn(?:ical|cial)\s+support|elcsupport/i.test(footerLinkDescription)) {
                            footerEventName = 'Technical support clicks';
                        } else if (/procurement.*shipping|shipping.*procurement/i.test(footerLinkDescription)) {
                            footerEventName = 'Procurement and Shipping clicks';
                        } else if (/instagram(?:\.com)?/i.test(footerLinkDescription)) {
                            footerEventName = 'Instagram clicks';
                        } else if (/linkedin(?:\.com)?/i.test(footerLinkDescription)) {
                            footerEventName = 'LinkedIn clicks';
                        }

                        if (footerEventName) {
                            sendClickEvent(footerEventName, {
                                link_text: cleanText(footerLink),
                                link_url: footerLink.href || '',
                                click_location: 'Footer'
                            });
                            return;
                        }
                    }

                    if (navigationItem && megaMenu && navigationItem.getAttribute('nav-item') === 'shop') {
                        sendClickEvent('Category click', {
                            category_name: cleanText(link),
                            link_url: link.href || '',
                            click_location: 'Shop mega menu'
                        });
                        return;
                    }

                    if (navigationItem && megaMenu && navigationItem.getAttribute('nav-item') === 'brands') {
                        sendClickEvent('Brand click', {
                            brand_id: link.getAttribute('data-account-brand-id') || '',
                            brand_name: cleanText(link),
                            link_url: link.href || '',
                            click_location: 'Brands mega menu'
                        });
                        return;
                    }

                    var launchProjectCta = /launch\s+a\s+project/i.test(cleanText(link))
                        && link.matches('a, button')
                        ? link
                        : null;
                    if (launchProjectCta) {
                        console.info('[Analytics] Launch a Project CTA captured:', launchProjectCta);
                        sendClickEvent('Launch a Project click', {
                            category_name: cleanText(document.querySelector('.top-category-hero__title'))
                                || cleanText(document.querySelector('.breadcrumbs .breadcrumb:last-child')),
                            cta_text: cleanText(launchProjectCta),
                            link_url: launchProjectCta.href || '',
                            click_location: 'Category hero'
                        });
                        return;
                    }

                    var productTrigger = link.closest('[data-event-type="product-click"]');
                    if (productTrigger) {
                        var card = productTrigger.closest('.card');

                        sendClickEvent('Product click', {
                            product_id: card ? card.getAttribute('data-entity-id') || '' : productTrigger.getAttribute('data-product-id') || '',
                            product_name: card ? card.getAttribute('data-name') || '' : cleanText(document.querySelector('.productView-title')),
                            product_brand: card ? card.getAttribute('data-product-brand') || '' : cleanText(document.querySelector('.productView-brand')),
                            product_category: card ? (card.getAttribute('data-product-category') || '').replace(/\s+/g, ' ').trim() : '',
                            product_price: card ? (card.getAttribute('data-product-price') || '').replace(/\s+/g, ' ').trim() : '',
                            product_position: card ? card.getAttribute('data-position') || '' : '',
                            click_text: cleanText(productTrigger),
                            click_location: '{{page_type}}',
                            link_url: productTrigger.href || ''
                        });
                        return;
                    }

                    var trendCard = link.closest('.inspired-card');
                    if (trendCard) {
                        var action = link.classList.contains('inspired-card__button--download')
                            ? 'download'
                            : link.classList.contains('inspired-card__button--view')
                                ? 'view'
                                : 'click';

                        sendClickEvent('Trend report click', {
                            report_name: cleanText(trendCard.querySelector('h3')),
                            report_meta: cleanText(trendCard.querySelector('.inspired-card__meta')),
                            action: action,
                            click_text: cleanText(link),
                            link_url: link.href || '',
                            click_location: "Home - Trends we're loving"
                        });
                    }
                }, true);
            }());
        </script>

        
    </body>
</html>

pages/page:
{{#partial "page"}}

{{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

<main class="page">
    {{#unless theme_settings.hide_page_heading }}
        <h1 class="page-heading">{{ page.title }}</h1>
    {{/unless}}

    {{#if page.sub_pages}}
    <nav class="navBar navBar--sub">
        <ul class="navBar-section account-navigation">
        {{#each page.sub_pages}}
            <li class="navBar-item"><a class="navBar-action" href="{{url}}">{{title}}</a></li>
        {{/each}}
        </ul>
    </nav>
    {{/if}}

    {{{region name="page_builder_content"}}}

    <div class="page-content page-content--centered">
        {{#replace '%%Syndicate%%' page.content}}
            {{> components/page/rss_feed}}
        {{else}}
            <p>{{{page.content}}}</p>
        {{/replace}}
    </div>

    {{#if page.feed}}
        <ul>
            {{#each page.feed}}
                <li>
                    <h6><a href="{{url}}" target="_blank">{{title}}</a></h6>
                    <p>{{content}}</p>
                </li>
            {{/each}}
        </ul>
    {{/if}}
</main>

{{/partial}}

{{> layout/base}}
